//! The figures the reports derive themselves, against an independent implementation in pandas
//! and NumPy. The fixture is generated by `scripts/reference/reports.py`.

#![allow(clippy::unwrap_used)]

use finalytics::formats::{CsvOptions, fx_from_csv, portfolio_from_csv, prices_from_csv};
use finalytics::reports::*;
use finalytics::{Books, Currency, Date, InstrumentId, MarketData};
use serde_json::Value;

const ACCOUNTS: &str = include_str!("../../../tests/scenario/accounts.csv");
const INSTRUMENTS: &str = include_str!("../../../tests/scenario/instruments.csv");
const TRANSACTIONS: &str = include_str!("../../../tests/scenario/transactions.csv");
const PRICES: &str = include_str!("../../../tests/scenario/prices.csv");
const FX: &str = include_str!("../../../tests/scenario/fx.csv");

fn setup() -> (Books, MarketData, Source) {
    let options = CsvOptions::default();
    let portfolio = portfolio_from_csv(
        Currency::USD,
        INSTRUMENTS,
        TRANSACTIONS,
        Some(ACCOUNTS),
        options,
    )
    .unwrap();
    let mut market = MarketData::new();
    for (id, prices) in prices_from_csv(PRICES, options).unwrap() {
        market = market.with_prices(id, prices);
    }
    for fx in fx_from_csv(FX, options).unwrap() {
        market = market.with_fx(fx.base, fx.quote, fx.rates);
    }
    let source = Source::of(&portfolio, &market);
    (Books::build(&portfolio, &market).unwrap(), market, source)
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/reports.json")).unwrap()
}

#[track_caller]
fn close(actual: f64, expected: &Value, what: &str) {
    let expected = expected.as_f64().unwrap();
    assert!(
        (actual - expected).abs() <= 1e-12 * expected.abs().max(1.0),
        "{what}: {actual} against the reference {expected}"
    );
}

fn d(s: &str) -> Date {
    s.parse().unwrap()
}

fn options() -> ReportOptions {
    {
        let mut report_options = ReportOptions::default();
        report_options.benchmark = Some(InstrumentId::new("SPY").unwrap());
        report_options
    }
}

#[test]
fn returns_by_month_year_and_period() {
    let (books, market, source) = setup();
    let f = fixture();
    let r = performance_report(&books, &market, &source, &options()).unwrap();
    assert_eq!(r.monthly.rows, ["2026"]);
    let row = &r.monthly.values[0];
    close(row[8].unwrap(), &f["months"]["2026-09"], "September");
    close(row[9].unwrap(), &f["months"]["2026-10"], "October");
    assert!(row[..8].iter().all(Option::is_none) && row[10..12].iter().all(Option::is_none));
    close(row[12].unwrap(), &f["years"]["2026"], "2026");
    let bench = &r.benchmark_monthly.as_ref().unwrap().values[0];
    close(
        bench[8].unwrap(),
        &f["benchmark_months"]["2026-09"],
        "benchmark September",
    );
    close(
        bench[9].unwrap(),
        &f["benchmark_months"]["2026-10"],
        "benchmark October",
    );
    let year = &r.calendar_years[0];
    assert!(!year.complete);
    close(
        year.benchmark.unwrap(),
        &f["benchmark_years"]["2026"],
        "benchmark 2026",
    );
    for label in ["MTD", "QTD", "ITD"] {
        let p = r.periods.iter().find(|p| p.label == label).unwrap();
        let e = &f["periods"][label];
        assert_eq!(p.start.unwrap(), d(e["start"].as_str().unwrap()), "{label}");
        close(p.cumulative.unwrap(), &e["cumulative"], label);
        close(p.benchmark.unwrap(), &e["benchmark"], label);
    }
    // The history does not reach back to the end of 2025.
    let ytd = r.periods.iter().find(|p| p.label == "YTD").unwrap();
    assert!(ytd.cumulative.is_none());
    for flows in &r.flows {
        let e = &f["flows"][&flows.month];
        close(flows.inflows, &e["inflows"], &flows.month);
        close(flows.outflows, &e["outflows"], &flows.month);
        close(flows.income, &e["income"], &flows.month);
    }
}

#[test]
fn concentration_and_the_return_distribution() {
    let (books, market, source) = setup();
    let f = fixture();
    let h = holdings_report(&books, &market, &source, &options()).unwrap();
    let c = &h.concentration;
    close(c.top_five, &f["concentration"]["top_five"], "top five");
    close(
        c.herfindahl.unwrap(),
        &f["concentration"]["herfindahl"],
        "Herfindahl",
    );
    close(
        c.effective_holdings.unwrap(),
        &f["concentration"]["effective_holdings"],
        "effective holdings",
    );
    let r = risk_report(&books, &market, &source, &options()).unwrap();
    let counts: Vec<u64> = r.histogram.bins.iter().map(|b| b.count as u64).collect();
    let expected: Vec<u64> = f["histogram"]["counts"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c.as_u64().unwrap())
        .collect();
    assert_eq!(counts, expected);
    close(r.histogram.bins[0].lower, &f["histogram"]["lower"], "lower");
    close(
        r.histogram.bins[29].upper,
        &f["histogram"]["upper"],
        "upper",
    );
}

#[test]
fn attribution_segments_from_the_books() {
    let (books, market, source) = setup();
    let f = fixture();
    let segment = |name: &str, w: f64, r: f64| BenchmarkSegment {
        name: name.into(),
        benchmark_weight: w,
        benchmark_return: r,
    };
    let mut options = options();
    options.attribution = Some(AttributionInputs {
        scheme: "asset_class".into(),
        periods: vec![
            BenchmarkPeriod {
                start: d("2026-09-01"),
                end: d("2026-09-30"),
                segments: vec![
                    segment("Equity", 0.6, -0.04),
                    segment("Fixed income", 0.4, 0.01),
                ],
            },
            BenchmarkPeriod {
                start: d("2026-09-30"),
                end: d("2026-10-30"),
                segments: vec![
                    segment("Equity", 0.6, -0.02),
                    segment("Fixed income", 0.4, 0.005),
                ],
            },
        ],
        linking: Default::default(),
    });
    let r = attribution_report(&books, &market, &source, &options).unwrap();
    let expected = f["attribution"].as_array().unwrap();
    for ((p, a), e) in r.periods.iter().zip(&r.attribution.periods).zip(expected) {
        let segments = e["segments"].as_array().unwrap();
        assert_eq!(p.segments.len(), segments.len());
        for ((s, x), e) in p.segments.iter().zip(&a.segments).zip(segments) {
            assert_eq!(s.name, e["name"].as_str().unwrap());
            let what = format!("{} {}", p.start, s.name);
            close(s.portfolio_weight, &e["portfolio_weight"], &what);
            close(s.portfolio_return, &e["portfolio_return"], &what);
            close(x.allocation, &e["allocation"], &what);
            close(x.selection, &e["selection"], &what);
            close(x.interaction, &e["interaction"], &what);
        }
    }
}
